SysDataModelXML.SQLScript:
-- 使用参数化变量 DECLARE @ITMREF VARCHAR(30) = '#产品编码#', @FCY VARCHAR(30) = '#地点#', @NEWLOC VARCHAR(30) = '#新库位#', @TAG VARCHAR(100) = '{0}';
DECLARE @StockCount INT; SELECT @StockCount = COUNT(*) FROM STOCK WHERE (ITMREF_0+LOT_0=@TAG OR SERNUM_0 = @TAG OR ZSTOFLD3_0=@TAG) AND STOFCY_0 = @FCY --AND ITMREF_0=@ITMREF-- 添加地点条件，减少数据量 AND LOC_0<>@NEWLOC;
IF @StockCount = 0 SELECT N'lang:{zh:扫描产品错误或无库存:,en:Scan product error or no stock:,de:Scan-Fehler oder kein Bestand:} ' + @TAG AS 数据检查; ELSE IF @StockCount > 1 SELECT N'lang:{zh:多个存库行，请选择,en:Multiple stock rows, please select,de:Mehrere Bestandszeilen, bitte wählen}' AS 数据检查; ELSE BEGIN -- 3. 优化主查询，使用CTE提高可读性 WITH XWSSummary AS ( SELECT STOCOU_0, SUM(QTYSTU_0) AS QTY FROM XWSSCS WHERE RPFLG_0 <> 3 GROUP BY STOCOU_0 ), StockData AS ( SELECT K.ITMREF_0, K.SERNUM_0, K.LOT_0, K.QTYSTU_0, K.CUMALLQTY_0, K.LOC_0, K.STA_0, K.PALNUM_0, K.STOCOU_0, K.ZSTOFLD3_0, -- 计算可用数量 K.QTYSTU_0 - ISNULL(XWS.QTY, 0) - K.CUMALLQTY_0 AS AvailableQty FROM STOCK K LEFT JOIN XWSSummary XWS ON XWS.STOCOU_0 = K.STOCOU_0 WHERE K.STOFCY_0 = @FCY AND K.LOC_0<>@NEWLOC --AND K.ITMREF_0=@ITMREF AND (K.ITMREF_0+K.LOT_0 = @TAG OR K.SERNUM_0 = @TAG OR K.ZSTOFLD3_0=@TAG) ) -- 4. 最终结果 SELECT ITMREF_0 AS 产品编码, CAST( CASE WHEN SERNUM_0 <> '' THEN 1 ELSE AvailableQty END AS REAL ) AS 数量, LOC_0 AS 原库位, ISNULL(NULLIF(SERNUM_0, ''), ZSTOFLD3_0) AS 序列号, LOT_0 AS 批次, CASE WHEN AvailableQty = 0 THEN N'lang:{zh:可用库存为0,en:Available stock is 0,de:Verfügbarer Bestand ist 0}' ELSE '' END AS 数据检查, STOCOU_0 AS STOCOU FROM StockData; END;
